66	  iter: AsyncIterable<string>,
67	  idleTimeoutMs: number,
68	  _signal: AbortSignal,
69	): AsyncGenerator<string> {
70	  const iterator = iter[Symbol.asyncIterator]();
71	  while (true) {
72	    let timeoutId: NodeJS.Timeout | undefined;
73	    const timeoutPromise = new Promise<never>((_, reject) => {
74	      if (idleTimeoutMs > 0) {
75	        timeoutId = setTimeout(() => reject(new Error("__idle__")), idleTimeoutMs);
