148	const GENERIC_PTC_RE = /^(be careful|make sure|consider|note that|avoid|watch out|don[\u0027\u2019]t forget)\b/i;
149	const MIN_SUMMARY_LEN = 20;
150	const MIN_PTC_ITEM_LEN = 15;
151	
152	export async function explain(
153	  segment: Segment,
154	  fileContext: string,
155	  deps: ExplanationDeps,
156	): Promise<Explanation> {
157	  // Rule 1 — input guard.
158	  const maxLines = deps.maxSegmentLines ?? DEFAULT_MAX_SEGMENT_LINES;
159	  const lineCount = segment.endLine - segment.startLine + 1;
160	  if (lineCount > maxLines) {
161	    throw new SegmentTooLargeError(segment.id, lineCount, maxLines);
162	  }
163	
164	  throwIfCancelled(deps.token);
165	
166	  const prompt = await loadPrompt(
167	    "explanation",
168	    {
169	      language: guessLanguage(segment),
170	      filename: "(unknown)",
171	      label: segment.label,
172	      startLine: String(segment.startLine),
173	      endLine: String(segment.endLine),
174	      blockCode: segment.code,
175	      fileContext: fileContext,
176	      additionalContext: deps.additionalContext ? `Prior context:\n${deps.additionalContext}` : "",
177	    },
178	    deps.promptsDir,
179	  );
180	
181	  const { system: baseSystem, user } = splitPrompt(prompt);
182	
183	  const idleTimeoutMs = deps.streamIdleTimeoutMs ?? DEFAULT_STREAM_IDLE_TIMEOUT_MS;
184	
185	  let firstRaw: string | undefined;
186	  let firstReason: string | undefined;
187	  let retryFired = false;
188	  const startMs = Date.now();
189	
190	  for (let attempt = 0; attempt < 2; attempt++) {
191	    if (attempt === 1) retryFired = true;
192	    throwIfCancelled(deps.token);
193	
194	    const system = attempt === 0
195	      ? baseSystem
196	      : `${baseSystem}\n\nCRITICAL: your previous response failed validation: ${firstReason ?? "unknown"}. Respond with ONLY the raw JSON object matching the schema. No preamble, no Markdown fence.`;
197	
198	    const messages: ChatMessage[] = [
199	      { role: "system", content: system },
200	      { role: "user", content: user },
201	    ];
202	
203	    let raw: string;
204	    if (attempt === 0 && deps.onPartial) {
205	      const ac = new AbortController();
206	      const tokenSub = deps.token?.onCancellationRequested(() => ac.abort());
207	      let buffer = "";
208	      let lastEmittedLength = 0;
209	      // DIAG(bug-A): remove after Phase 2 streaming verified.
210	      const streamStartMs = Date.now();
211	      let chunkCount = 0;
212	      let partialCount = 0;
213	      let firstChunkMs: number | undefined;
214	      let firstPartialMs: number | undefined;
215	      try {
216	        const stream = deps.adapter.completeStream(messages, {
217	          responseFormat: "json_object",
218	          jsonSchema: EXPLANATION_JSON_SCHEMA,
219	          signal: ac.signal,
220	          idleTimeoutMs,
221	        });
222	        deps.logger?.(`[explain-diag] stream opened segmentId=${segment.id}`);
223	        for await (const chunk of streamWithIdleTimeout(stream, idleTimeoutMs, ac.signal)) {
224	          chunkCount++;
225	          if (firstChunkMs === undefined) firstChunkMs = Date.now() - streamStartMs;
226	          buffer += chunk;
227	          const partial = extractPartialSummary(buffer);
228	          if (partial !== undefined && partial.length > lastEmittedLength) {
229	            partialCount++;
230	            if (firstPartialMs === undefined) firstPartialMs = Date.now() - streamStartMs;
231	            deps.logger?.(`[explain-diag] partial #${partialCount} ms=${Date.now() - streamStartMs} len=${partial.length}`);
232	            deps.onPartial({ summary: partial });
233	            lastEmittedLength = partial.length;
234	          }
235	        }
236	        deps.logger?.(
237	          `[explain-diag] stream closed segmentId=${segment.id} totalMs=${Date.now() - streamStartMs} `
238	          + `chunks=${chunkCount} partials=${partialCount} `
239	          + `firstChunkMs=${firstChunkMs ?? -1} firstPartialMs=${firstPartialMs ?? -1} `
240	          + `bufferLen=${buffer.length}`,
241	        );
242	        raw = buffer;
243	      } catch (err) {
244	        if (tokenSub) tokenSub.dispose();
245	        if (err instanceof CancelledError) throw err;
246	        if (err instanceof AuthError || err instanceof RateLimitError) throw err;
247	        if ((err as Error).message === "__idle__" || err instanceof StreamIdleTimeoutError) {
248	          throw new ExplanationStreamError(segment.id, buffer.length, "provider-terminated");
249	        }
250	        throw new ExplanationStreamError(segment.id, buffer.length, "network");
251	      } finally {
252	        if (tokenSub) tokenSub.dispose();
253	      }
254	    } else {
255	      raw = await deps.adapter.complete(
256	        messages,
257	        { responseFormat: "json_object", jsonSchema: EXPLANATION_JSON_SCHEMA },
258	      );
259	    }
260	
261	    try {
262	      const validated = validateResponse(raw, segment, deps.logger);
263	      const modelTimeMs = Date.now() - startMs;
264	      const prefix = retryFired ? "[explanation] WARN" : "[explanation]";
265	      deps.logger?.(
266	        `${prefix} segmentId=${segment.id} summary=${validated.summary.length}ch `
267	        + `assumptions=${validated.pointsToConsider.assumptions.length} `
268	        + `dangers=${validated.pointsToConsider.dangers.length} `
269	        + `sideEffects=${validated.pointsToConsider.sideEffects.length} `
270	        + `concepts=${validated.concepts.length} `
271	        + `modelTimeMs=${modelTimeMs} retryFired=${retryFired}`,
272	      );
273	      return {
274	        segmentId: segment.id,
275	        summary: validated.summary,
276	        pointsToConsider: validated.pointsToConsider,
277	        concepts: validated.concepts,
278	        renderState: "done",
279	      };
280	    } catch (err) {
281	      if (err instanceof ValidationFailure) {
282	        // DIAG(bug-C): remove after Phase 2 Anthropic path verified.
283	        deps.logger?.(`[explain-diag] validation failed attempt=${attempt} reason="${err.message}" rawPrefix=${JSON.stringify(raw.slice(0, 300))}`);
284	        if (attempt === 0) {
285	          firstRaw = raw;
286	          firstReason = err.message;
287	          continue;
288	        }
289	        throw new MalformedResponseError(
290	          `validation failed on both attempts: ${err.message}`,
291	          JSON.stringify({ first: firstRaw, second: raw }),
292	        );
293	      }
294	      throw err;
295	    }
296	  }
297	  throw new Error("unreachable");
298	}
299	
300	function throwIfCancelled(token?: vscode.CancellationToken): void {
301	  if (token?.isCancellationRequested) throw new CancelledError();
302	}
303	
304	function splitPrompt(prompt: string): { system: string; user: string } {
305	  const marker = "## Input";
306	  const idx = prompt.indexOf(marker);
307	  if (idx < 0) return { system: prompt, user: "" };
308	  return {
309	    system: prompt.slice(0, idx).trim(),
310	    user: prompt.slice(idx + marker.length).trim(),
311	  };
312	}
313	
314	function guessLanguage(segment: Segment): string {
315	  // Pragmatic guess; production code can pull from vscode.TextDocument.languageId.
316	  return (segment as unknown as { languageId?: string }).languageId ?? "text";
317	}
318	
319	function validateResponse(raw: string, segment: Segment, logger?: ExplanationLogger): {
320	  summary: string;
321	  pointsToConsider: Explanation["pointsToConsider"];
322	  concepts: Concept[];
323	} {
324	  let obj: RawExplanation;
325	  try {
326	    obj = JSON.parse(raw);
327	  } catch {
328	    throw new ValidationFailure("response is not valid JSON");
329	  }
330	
331	  if (typeof obj.summary !== "string" || obj.summary.length < MIN_SUMMARY_LEN) {
332	    throw new ValidationFailure(`summary is missing or shorter than ${MIN_SUMMARY_LEN} chars`);
333	  }
334	  if (obj.summary.trim().toLowerCase() === segment.oneLiner.trim().toLowerCase()) {
335	    throw new ValidationFailure("summary is identical to segment.oneLiner — agent must expand on the one-liner, not echo it");
336	  }
337	
338	  const ptcIn = obj.pointsToConsider ?? {};
339	  const pointsToConsider = {
340	    assumptions: filterPtcItems(ptcIn.assumptions),
341	    dangers: filterPtcItems(ptcIn.dangers),
342	    sideEffects: filterPtcItems(ptcIn.sideEffects),
343	  };
344	
345	  const conceptsRaw = Array.isArray(obj.concepts) ? obj.concepts : [];
346	  // DIAG(bug-B): remove after Phase 2 concepts rendering verified.
347	  logger?.(`[explain-diag] concepts raw count: ${conceptsRaw.length}; rawKeys=${JSON.stringify(conceptsRaw.map((c: any) => (c && typeof c === "object") ? Object.keys(c) : typeof c))}`);
348	  const concepts: Concept[] = [];
349	  const seen = new Set<string>();
350	  for (const c of conceptsRaw) {
351	    if (!c || typeof (c as any).name !== "string" || (c as any).name.length === 0) {
352	      logger?.(`[explain-diag] concept dropped: missing/empty name; raw=${JSON.stringify(c).slice(0, 200)}`);
353	      continue;
354	    }
355	    if (typeof (c as any).briefExplainer !== "string" || (c as any).briefExplainer.length === 0) {
356	      logger?.(`[explain-diag] concept dropped: missing/empty briefExplainer; name="${(c as any).name}"`);
357	      continue;
358	    }
359	    if (typeof (c as any).relevance !== "string" || (c as any).relevance.length === 0) {
360	      logger?.(`[explain-diag] concept dropped: missing/empty relevance; name="${(c as any).name}"`);
361	      continue;
362	    }
363	    const key = (c as any).name.trim().toLowerCase();
364	    if (seen.has(key)) {
365	      logger?.(`[explain-diag] concept dropped: duplicate name="${(c as any).name}"`);
366	      continue;
367	    }
368	    seen.add(key);
369	    concepts.push({
370	      name: (c as any).name,
371	      briefExplainer: (c as any).briefExplainer,
372	      relevance: (c as any).relevance,
373	    });
374	  }
375	
376	  return { summary: obj.summary, pointsToConsider, concepts };
377	}
378	
379	function filterPtcItems(x: unknown): string[] {
380	  if (!Array.isArray(x)) return [];
381	  return x.filter(
382	    (s): s is string =>
383	      typeof s === "string"
384	      && s.length >= MIN_PTC_ITEM_LEN
385	      && !GENERIC_PTC_RE.test(s.trim()),
386	  );
387	}
