1	import * as vscode from "vscode";
2	import type { Segment } from "../types";
3	import type { ExplanationDeps } from "./explanationAgent";
4	import { explain } from "./explanationAgent";
5	import type { ExplanationStore } from "./explanationStore";
6	import { AuthError } from "../llm/adapter";
7	
8	export interface PrefetchQueueDeps {
9	  readonly explanationStore: ExplanationStore;
10	  readonly agentDeps: Pick<ExplanationDeps, "adapter" | "promptsDir" | "structuredOutputMode">;
11	  readonly preset: string;
12	  readonly promptVersion: string;
13	  readonly logger?: (msg: string) => void;
14	  readonly concurrency?: number;
15	}
16	
17	interface Job {
18	  segment: Segment;
19	  uri: vscode.Uri;
20	}
21	
22	export class PrefetchQueue implements vscode.Disposable {
23	  private readonly concurrency: number;
24	  private readonly perUriTokens = new Map<string, vscode.CancellationTokenSource>();
25	  private disabled = false;
26	  private drainPromise: Promise<void> = Promise.resolve();
27	
28	  constructor(private readonly deps: PrefetchQueueDeps) {
29	    this.concurrency = deps.concurrency ?? 2;
30	  }
31	
32	  enqueueAll(uri: vscode.Uri, segments: readonly Segment[]): void {
33	    if (this.disabled) return;
34	    // Cancel any in-flight work for this URI and replace.
35	    const existing = this.perUriTokens.get(uri.toString());
36	    if (existing) {
37	      existing.cancel();
38	      existing.dispose();
39	    }
40	    const source = new vscode.CancellationTokenSource();
41	    this.perUriTokens.set(uri.toString(), source);
42	
43	    const needsFetch = segments.filter(seg => {
44	      const cached = this.deps.explanationStore.get(seg.id, this.deps.preset, this.deps.promptVersion);
45	      return !cached || cached.renderState !== "done";
46	    });
47	
48	    const jobs: Job[] = needsFetch.map(segment => ({ segment, uri }));
49	    this.drainPromise = this.drainPromise.then(() => this.runBatch(jobs, source.token));
50	  }
51	
52	  cancelAll(): void {
53	    for (const src of this.perUriTokens.values()) {
54	      src.cancel();
55	      src.dispose();
56	    }
57	    this.perUriTokens.clear();
58	  }
59	
60	  /** Test hook — resolves when the latest enqueued batch has fully settled. */
61	  drain(): Promise<void> {
62	    return this.drainPromise;
63	  }
64	
65	  dispose(): void {
66	    this.cancelAll();
67	  }
68	
69	  private async runBatch(jobs: Job[], token: vscode.CancellationToken): Promise<void> {
70	    const workers: Promise<void>[] = [];
71	    let cursor = 0;
72	    const next = async (): Promise<void> => {
73	      while (cursor < jobs.length && !this.disabled && !token.isCancellationRequested) {
74	        const i = cursor++;
75	        const job = jobs[i]!;
76	        try {
77	          // Mark streaming placeholder so concurrent user clicks know an agent is working.
78	          this.deps.explanationStore.set(job.segment.id, this.deps.preset, this.deps.promptVersion, {
79	            segmentId: job.segment.id,
80	            summary: "",
81	            pointsToConsider: { assumptions: [], dangers: [], sideEffects: [] },
82	            concepts: [],
83	            renderState: "streaming",
84	          });
85	          const exp = await explain(job.segment, "", {
86	            adapter: this.deps.agentDeps.adapter,
87	            promptsDir: this.deps.agentDeps.promptsDir,
88	            structuredOutputMode: this.deps.agentDeps.structuredOutputMode,
89	            logger: this.deps.logger,
90	            token,
91	          });
92	          this.deps.explanationStore.set(job.segment.id, this.deps.preset, this.deps.promptVersion, exp);
93	        } catch (err) {
94	          if (err instanceof AuthError) {
95	            this.disabled = true;
96	            this.deps.logger?.(`[prefetch] disabled: auth failed — fix API key and reload`);
97	            return;
98	          }
99	          this.deps.logger?.(`[prefetch] error segmentId=${job.segment.id} reason=${(err as Error).message}`);
100	        }
101	      }
102	    };
103	    for (let i = 0; i < Math.min(this.concurrency, jobs.length); i++) workers.push(next());
104	    await Promise.all(workers);
105	  }
106	}
