const PURPOSE_RE = /"purpose"\s*:\s*"((?:[^"\\]|\\.)*)/;

export function extractPartialPurpose(buffer: string): string | undefined {
  const match = PURPOSE_RE.exec(buffer);
  if (!match) return undefined;
  try {
    return JSON.parse(`"${match[1]}"`);
  } catch {
    return undefined;
  }
}
