const GENERIC_PTC_RE = /^(be careful|make sure|consider|note that|avoid|watch out|don['’]t forget)\b/i;
const MIN_PURPOSE_LEN = 20;
const MIN_LIST_ITEM_LEN = 15;
const CAP_FLOW = 5;
const CAP_USES = 5;
const CAP_PRODUCES = 3;
const CAP_WATCH = 3;
const CAP_CONCEPTS = 3;
```

